def find_kth(arr1, arr2, k):
    if k < 1 or k > len(arr1) + len(arr2):
        raise IndexError("k is out of the bounds of the combined arrays")

    def kth_helper(a, b, k):
        if not a:
            return b[k-1]
        if not b:
            return a[k-1]
        if k == 1:
            return min(a[0], b[0])

        i = min(len(a), k // 2)
        j = min(len(b), k // 2)

        if a[i - 1] <= b[j - 1]:
            return kth_helper(a[i:], b, k - i)
        else:
            return kth_helper(a, b[j:], k - j)

    return kth_helper(arr1, arr2, k)
```

