def max_path_sum(triangle):
    if not triangle:
        return 0
    # Copy the last row as the initial max sums
    max_sums = triangle[-1][:]
    # Start from the second last row and move upwards
    for row in range(len(triangle) - 2, -1, -1):
        for col in range(len(triangle[row])):
            # Update max_sums[col] with the max path sum from this position
            max_sums[col] = triangle[row][col] + max(max_sums[col], max_sums[col + 1])
    return max_sums[0]
```

