def max_product(nums):
    if not nums:
        return 0

    n = len(nums)
    dp = nums[:]  # dp[i] will store the max product of increasing subsequence ending at i

    for i in range(n):
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i], dp[j] * nums[i])

    return max(dp)
```

