def min_coins(coins, value):
    # Initialize DP array where dp[i] will store the minimum number of coins for amount i
    dp = [float('inf')] * (value + 1)
    dp[0] = 0  # 0 coins needed to make value 0

    for i in range(1, value + 1):
        for coin in coins:
            if coin <= i:
                dp[i] = min(dp[i], dp[i - coin] + 1)

    return dp[value] if dp[value] != float('inf') else -1
```

