        while y:
            x, y = y, x % y
        return x

    g = gcd(abs(a), abs(b))
    total = 0
    i = 1
    while i * i <= g:
        if g % i == 0:
            total += i
            if i != g // i:
                total += g // i
        i += 1
    return total
