def order_by_points(nums):
    def digit_sum(n):
        s = str(abs(n))
        digits = list(map(int, s))
        if n >= 0:
            return sum(digits)
        else:
            # For negative numbers, negate only the first digit before summing the rest
            return -digits[0] + sum(digits[1:])
    return sorted(nums, key=lambda x: digit_sum(x))
