        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5)+1, 2):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    prime_length_words = [w for w in words if is_prime(len(w))]
    return " ".join(prime_length_words)
