def get_closest_vowel(word):
    vowels = "aeiouAEIOU"
    length = len(word)
    # Iterate from right to left, excluding first and last characters
    for i in range(length - 2, 0, -1):
        if word[i] in vowels:
            # Check if neighbors are consonants (letters not in vowels)
            if (word[i-1].isalpha() and word[i-1] not in vowels) and (word[i+1].isalpha() and word[i+1] not in vowels):
                return word[i]
    return ""
